"""System Design and Databases for Product Managers: inventory, checkout, SQL, NoSQL, Cassandra, Paxos, vector DBs and more, in plain words."""
from coursekit import ill_flow, ill_cycle, ill_quad, ill_stack, _txt, _fig

def arch():
    """The whiteboard: users, app, services, payment, vendors, databases, vector DB and a consensus ring."""
    def box(x, y, w, h, label, col="#6C4CF5", n=14):
        return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="10" fill="{col}" fill-opacity=".13" stroke="{col}" stroke-width="2"/>' + _txt(x + w / 2, y + h / 2 + 4, label, n, 11.5)
    def db(x, y, label, col):
        return (f'<path d="M{x} {y+8} v42 a38 8 0 0 0 76 0 v-42" fill="{col}" fill-opacity=".13" stroke="{col}" stroke-width="2"/><ellipse cx="{x+38}" cy="{y+8}" rx="38" ry="8" fill="{col}" fill-opacity=".25" stroke="{col}" stroke-width="2"/>'
                + _txt(x + 38, y + 36, label, 11, 11))
    def ar(x1, y1, x2, y2): return f'<path d="M{x1} {y1} L{x2} {y2}" stroke="#8a86a8" stroke-width="2" fill="none" marker-end="url(#ah)"/>'
    s = '<defs><marker id="ah" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 z" fill="#8a86a8"/></marker></defs>'
    s += box(10, 150, 80, 44, "User", "#16A34A") + box(120, 150, 90, 44, "App UI", "#6C4CF5")
    s += box(120, 40, 90, 44, "Geolocation", "#0E9FB8") + box(120, 250, 90, 44, "Chatbot", "#DB2777")
    s += box(250, 250, 100, 44, "Customer support", "#DB2777", 12)
    s += box(250, 140, 110, 64, "Service (API, order logic)", "#2E3192", 14)
    s += box(400, 40, 90, 44, "Payment", "#D97706") + box(250, 40, 90, 44, "Vendor app", "#16A34A")
    s += db(400, 130, "Inventory (NoSQL)", "#0E9FB8") + db(400, 240, "Orders (SQL)", "#6C4CF5") + db(560, 240, "Vector DB", "#DB2777")
    s += box(560, 40, 150, 40, "Consensus: Paxos / Raft", "#2E3192", 22)
    for cx, cy in [(600, 130), (660, 130), (630, 175)]:
        s += f'<circle cx="{cx}" cy="{cy}" r="16" fill="#2E3192" fill-opacity=".15" stroke="#2E3192" stroke-width="2"/><text x="{cx}" y="{cy+4}" text-anchor="middle" font-family="Inter,Arial" font-size="10" font-weight="700" fill="#14112a">Node</text>'
    s += ar(90, 172, 118, 172) + ar(165, 150, 165, 88) + ar(210, 172, 248, 172) + ar(305, 140, 305, 88) + ar(360, 160, 398, 100) + ar(360, 182, 398, 165) + ar(360, 198, 398, 255)
    s += ar(165, 194, 165, 248) + ar(210, 272, 248, 272) + ar(355, 272, 398, 272) + ar(476, 280, 558, 280) + ar(476, 160, 584, 150)
    return _fig(s, 730, 320, "The whiteboard as a system: what talks to what when a customer taps Buy", 720)

def tpl(name, rows): return f"<h3>{name}</h3><table><tr><th>Field</th><th>Fill in</th></tr>" + "".join(f"<tr><td>{r}</td><td></td></tr>" for r in rows) + "</table>"

CLASSES = [
 ("basic", "The big picture: what happens when you tap Buy", "See every box on the whiteboard in plain words.", arch() + r"""
<p>Imagine a quick-commerce app like Zepto or Blinkit. You open it, see milk, tap <b>Buy</b>. In about two seconds, a dozen systems cooperate. Here is each box, explained for a non-technical PM.</p>
<table><tr><th>Box</th><th>Plain-words job</th><th>Everyday comparison</th></tr>
<tr><td><b>User / App UI</b></td><td>The screen you tap. It asks the service for data and shows the answer.</td><td>The shop counter</td></tr>
<tr><td><b>Geolocation</b></td><td>Finds where you are and which nearby store can deliver.</td><td>Google Maps on the counter</td></tr>
<tr><td><b>Service (API)</b></td><td>The brain with the business rules: check stock, price, create the order. Many small services is called <i>microservices</i>.</td><td>The shop manager</td></tr>
<tr><td><b>Inventory database</b></td><td>Stores how many items each store has. Read thousands of times a second.</td><td>The stock register</td></tr>
<tr><td><b>Orders database (SQL)</b></td><td>Stores orders, payments, refunds exactly and safely.</td><td>The cash book</td></tr>
<tr><td><b>Payment</b></td><td>Talks to UPI, cards and wallets through a gateway such as Razorpay.</td><td>The card machine</td></tr>
<tr><td><b>Vendor app</b></td><td>The store or seller updates stock and prices and accepts orders.</td><td>The shopkeeper's phone</td></tr>
<tr><td><b>Chatbot + customer support</b></td><td>Answers "where is my order?" and hands tough cases to humans.</td><td>The help desk</td></tr>
<tr><td><b>Vector database</b></td><td>Lets AI search by meaning, so the chatbot finds the right help article.</td><td>A librarian who understands what you mean</td></tr>
<tr><td><b>Consensus nodes (Paxos / Raft)</b></td><td>A few servers that must agree on one truth, even if one fails.</td><td>Four partners who must agree on the same ledger</td></tr></table>
<div class="box"><b>Your job as a PM</b> is not to draw this perfectly. It is to ask the right "what happens when…" questions: when two people buy the last item, when payment fails after stock is taken, when a server dies on sale day.</div>""",
  ["Every tap triggers many systems working together.", "Each box has one job; failures happen between boxes.", "You do not build it, but you must be able to question it."], "Draw your favourite app's Buy flow with 8 boxes and write one 'what if this fails?' question for each arrow."),

 ("basic", "Why PMs need this: the business view", "Connect technical choices to money, trust and speed.", r"""
<p>System design looks technical, but every choice is a business trade-off. Engineers decide <i>how</i>; PMs decide <i>what matters most</i>. Without that, teams over-build or under-protect.</p>
<table><tr><th>Business goal</th><th>Technical lever</th><th>PM decision</th></tr>
<tr><td>More sales</td><td>Fast pages and search (caching, indexes, CDN)</td><td>What is our target load time on a 4G phone?</td></tr>
<tr><td>Customer trust</td><td>No double charge, no oversold stock (transactions, idempotency)</td><td>Which actions must never be wrong, even if slower?</td></tr>
<tr><td>Sale-day survival</td><td>Scaling, queues, replicas, load tests</td><td>What traffic do we plan for, 5x or 20x?</td></tr>
<tr><td>Lower cost per order</td><td>Right database for each job, storage tiers</td><td>What can we afford per 1,000 orders?</td></tr>
<tr><td>Legal safety</td><td>Encryption, data location, access control (DPDP Act, RBI rules, PCI-DSS)</td><td>Which data is sensitive, and who may see it?</td></tr>
<tr><td>Fast shipping of features</td><td>Clear services and APIs</td><td>Which team owns which part?</td></tr></table>
<h3>Numbers PMs should know</h3><ul><li><b>Latency:</b> time for one request. Watch <b>p95/p99</b> (the slow 5% or 1% of users), not only the average.</li><li><b>Availability:</b> 99.9% allows about 8.8 hours of downtime a year; 99.99% only about 53 minutes.</li><li><b>SLA / SLO / SLI:</b> the promise to customers / the internal target / the measured number.</li><li><b>RPO / RTO:</b> how much data you can lose / how long you can be down after a disaster.</li></ul>
<div class="box">A cheap rule: <b>spend reliability budget where mistakes cost real money or trust</b> (payments, stock, personal data) and accept simpler, cheaper setups where a small error is harmless (likes, view counts).</div>""",
  ["Technical choices are business trade-offs.", "Protect money, stock and personal data first.", "Ask for p95/p99 and availability targets in every spec."], "Pick a feature you own. List the one thing that must never be wrong and the one thing that can be a little stale."),

 ("basic", "SQL databases in plain words", "Understand tables, keys, joins and indexes without code fear.", ill_stack([("Application / service", "asks questions in SQL"), ("Database engine", "plans and runs the query"), ("Indexes", "shortcuts so it does not read every row"), ("Tables on disk", "rows and columns, linked by keys")], "How a SQL database answers a question") + r"""
<p>A SQL (relational) database is a set of tables, like linked Excel sheets. Each row is a record; <b>keys</b> link rows across tables. SQL is the language to ask questions. Examples: PostgreSQL, MySQL, SQL Server, Oracle.</p>
<table><tr><th>Table</th><th>Columns</th></tr><tr><td>products</td><td>product_id (key), name, price</td></tr><tr><td>inventory</td><td>store_id, product_id, qty, state</td></tr><tr><td>orders</td><td>order_id (key), user_id, store_id, total, status</td></tr></table>
<pre>-- How many packets of milk are available in store 7?
SELECT qty FROM inventory
WHERE store_id = 7 AND product_id = 42 AND state = 'available';</pre>
<ul><li><b>Primary key:</b> the unique ID of a row. <b>Foreign key:</b> a column pointing to another table's key.</li><li><b>Join:</b> combine tables ("orders with the customer's name").</li><li><b>Index:</b> a lookup shortcut, like a book's index. Makes reads fast but writes a little slower and uses space.</li><li><b>Schema:</b> the fixed structure of tables. Changing it needs a planned migration.</li></ul>
<div class="box"><b>Choose SQL when</b> data is structured, relationships matter, and correctness is critical: orders, payments, accounts, bookings, reports.</div>""",
  ["SQL = tables with keys, queried by joins.", "Indexes trade write speed for read speed.", "Default to SQL for money and orders."], "Sketch three tables for a food-delivery app and mark the primary and foreign keys."),

 ("basic", "ACID: why money and stock stay correct", "Learn the four promises of a database transaction.", r"""
<p>A <b>transaction</b> groups steps so they succeed or fail together. Example: buying the last milk packet means (1) reduce stock, (2) create the order, (3) record the payment. If step 3 fails, steps 1 and 2 must undo.</p>
<table><tr><th>Letter</th><th>Promise</th><th>Plain example</th></tr>
<tr><td><b>A</b>tomicity</td><td>All steps happen or none do</td><td>Money leaves your account only if it reaches the shop</td></tr>
<tr><td><b>C</b>onsistency</td><td>Rules always hold</td><td>Stock never goes below zero</td></tr>
<tr><td><b>I</b>solation</td><td>Simultaneous users do not corrupt each other</td><td>Two buyers cannot both get the last item</td></tr>
<tr><td><b>D</b>urability</td><td>Once confirmed, it survives a crash</td><td>Your order still exists after a power cut</td></tr></table>
<pre>BEGIN;
UPDATE inventory SET qty = qty - 1
  WHERE store_id = 7 AND product_id = 42 AND qty > 0;
INSERT INTO orders (user_id, store_id, status) VALUES (101, 7, 'created');
COMMIT;   -- or ROLLBACK if anything failed</pre>
<div class="box">Transactions are why SQL databases are trusted for payments. Many NoSQL databases trade some of these promises for speed and scale, which is the key trade-off in the next classes.</div>""",
  ["Transaction = all-or-nothing group of steps.", "ACID protects money and stock.", "Isolation is the promise behind 'no double selling'."], "Write the steps of a UPI payment and mark which must be all-or-nothing."),

 ("intermediate", "NoSQL: the main types and when to use them", "Pick between key-value, document, wide-column and graph stores.", ill_quad("Data structure complexity", "Scale and speed need", ["Key-value: Redis, DynamoDB", "Wide-column: Cassandra", "Document: MongoDB", "Graph: Neo4j"], "Where each NoSQL type fits") + r"""
<p><b>NoSQL</b> means "not only SQL": databases that skip fixed tables and joins to scale across many servers and handle flexible data. They usually relax some ACID promises for speed (see BASE in class 7).</p>
<table><tr><th>Type</th><th>Shape</th><th>Good for</th><th>Examples</th></tr>
<tr><td>Key-value</td><td>One key → one value</td><td>Sessions, carts, caches, counters, feature flags</td><td>Redis, DynamoDB</td></tr>
<tr><td>Document</td><td>JSON-like documents</td><td>Product catalogue, user profiles with varied fields</td><td>MongoDB, Firestore</td></tr>
<tr><td>Wide-column</td><td>Rows grouped by a partition key, huge and sparse</td><td>Messages, activity feeds, time-series, IoT, write-heavy data</td><td>Cassandra, ScyllaDB, HBase</td></tr>
<tr><td>Graph</td><td>Nodes and relationships</td><td>Friends, fraud rings, recommendations</td><td>Neo4j, Neptune</td></tr>
<tr><td>Vector</td><td>Numbers that capture meaning</td><td>AI search and chatbots (class 14)</td><td>Pinecone, pgvector, Qdrant</td></tr></table>
<h3>SQL vs NoSQL in one table</h3><table><tr><th></th><th>SQL</th><th>NoSQL</th></tr><tr><td>Structure</td><td>Fixed tables</td><td>Flexible</td></tr><tr><td>Relationships</td><td>Joins are easy</td><td>Usually avoided or hand-built</td></tr><tr><td>Consistency</td><td>Strong (ACID)</td><td>Often eventual, tunable</td></tr><tr><td>Scaling</td><td>Vertical first, harder to spread</td><td>Built to spread across many servers</td></tr><tr><td>Best for</td><td>Orders, payments, reports</td><td>High-volume reads/writes, flexible data</td></tr></table>
<div class="box"><b>Common real-world answer:</b> use both. SQL for orders and money, NoSQL (Redis/Cassandra/Mongo) for carts, catalogue, feeds and caches. This is called <i>polyglot persistence</i>.</div>""",
  ["NoSQL has four main shapes plus vector.", "It trades some consistency for scale and flexibility.", "Most products use SQL and NoSQL together."], "Match five data types in a food app (cart, orders, menu, chat, ratings) to a database type."),

 ("intermediate", "Cassandra explained for PMs", "Understand a masterless, always-on database.", ill_cycle(["Node A", "Node B", "Node C", "Node D"], "Cassandra ring: every node is equal, data is copied to several") + r"""
<p><b>Apache Cassandra</b> is a wide-column NoSQL database built so there is <b>no single point of failure</b>. All servers (nodes) are equal and form a ring. It is popular where data arrives constantly and downtime is unacceptable: messages, activity feeds, order status events, sensor data.</p>
<ul><li><b>Partition key:</b> the field that decides which node stores a row (for example <code>store_id</code>). Chosen badly, one node gets overloaded (a "hot partition").</li><li><b>Replication factor (RF):</b> how many copies exist. RF=3 means each row lives on three nodes.</li><li><b>Tunable consistency:</b> per query you choose how many copies must answer. <b>ONE</b> = fastest, maybe stale; <b>QUORUM</b> = majority, safer; <b>ALL</b> = strongest, slowest.</li><li><b>Fast writes:</b> it appends data first and tidies later (an LSM-tree design).</li><li><b>Query-first design:</b> you design tables around the questions you will ask. Ad hoc queries and joins are weak.</li></ul>
<table><tr><th>Strengths</th><th>Weaknesses</th></tr><tr><td>Writes at massive scale, multi-region, survives node loss</td><td>No joins, limited ad hoc queries, transactions are limited and slow</td></tr><tr><td>Linear scale: add nodes to add capacity</td><td>Needs careful data modelling and operations skills</td></tr></table>
<h3>LWT (lightweight transactions) and the other terms you will hear</h3>
<p><b>LWT</b> is Cassandra's way to do a safe "check, then write" in one step, for example <code>INSERT … IF NOT EXISTS</code> (claim a username, create an order once) or <code>UPDATE … IF qty &gt; 0</code>. Under the hood the replicas run a <b>Paxos</b> round (class 14) to agree, so it needs several network round trips: about 4 instead of 1. It is correct but <b>much slower</b> and gets worse when many people fight for the same row. Use it sparingly (claiming a unique ID, one-time actions), never on the hot path of every click.</p>
<pre>INSERT INTO orders_by_key (idempotency_key, order_id, user_id)
VALUES ('chk-7f3a', 55, 101) IF NOT EXISTS;   -- LWT: only the first request wins</pre>
<table><tr><th>Term</th><th>Plain meaning</th></tr>
<tr><td><b>CQL</b></td><td>Cassandra's SQL-like query language</td></tr>
<tr><td><b>Partition key / clustering key</b></td><td>Partition key decides <i>which node</i>; clustering key decides <i>the order of rows inside</i> that partition (for example newest first)</td></tr>
<tr><td><b>Consistency levels</b></td><td>ONE (fast), QUORUM (majority), LOCAL_QUORUM (majority inside one data centre, the usual choice for multi-region), ALL (every copy), SERIAL (used by LWT)</td></tr>
<tr><td><b>Gossip</b></td><td>Nodes chat with each other to learn who is up or down; no central boss</td></tr>
<tr><td><b>Commit log + memtable + SSTable</b></td><td>A write goes to a safety log and to memory first, then is flushed to immutable files on disk (SSTables). This is why writes are fast</td></tr>
<tr><td><b>Compaction</b></td><td>Background merging of SSTables to keep reads fast and reclaim space</td></tr>
<tr><td><b>Tombstone</b></td><td>A delete marker. Many tombstones slow reads, so avoid patterns that delete constantly (queues in a table)</td></tr>
<tr><td><b>TTL</b></td><td>Time to live: rows that expire automatically (OTPs, sessions, 8-minute stock holds)</td></tr>
<tr><td><b>Hinted handoff, read repair, anti-entropy repair</b></td><td>The ways copies that missed a write catch up, so replicas converge (eventual consistency)</td></tr>
<tr><td><b>Replication strategy / data centre</b></td><td>NetworkTopologyStrategy places copies across racks and regions; this is how Cassandra survives a whole data centre going down</td></tr>
<tr><td><b>Vnodes</b></td><td>Each server owns many small slices of the ring so data spreads evenly and new nodes take load smoothly</td></tr>
<tr><td><b>Denormalisation</b></td><td>Store the same data in several tables, one per query, because there are no joins</td></tr></table>
<div class="box"><b>PM question:</b> "Do we need always-on writes at huge scale, or do we need strict transactions?" If the answer is strict transactions (payments, stock decrement), choose SQL or a database with strong transactions instead.</div>""",
  ["Cassandra = equal nodes in a ring, data copied several times.", "You choose consistency per query.", "Great for high-volume writes, poor for joins and strict transactions.", "LWT adds safe check-then-write using Paxos, but is slow: use it sparingly."], "List three features in a delivery app that fit Cassandra (hint: tracking pings, chat, event logs) and one that does not."),

 ("intermediate", "Scaling data: replication, sharding, caching, CAP and BASE", "Know how products stay fast and available as they grow.", ill_stack([("CDN / edge", "images and static files near the user"), ("Cache (Redis)", "hot data in memory, microseconds"), ("Read replicas", "copies that answer reads"), ("Primary database", "the one place that accepts writes"), ("Shards", "data split across many databases")], "From the user to the data: layers that make products fast") + r"""
<table><tr><th>Technique</th><th>Plain meaning</th><th>Trade-off</th></tr>
<tr><td><b>Replication</b></td><td>Keep copies on several servers for safety and read speed</td><td>Copies can lag (stale reads)</td></tr>
<tr><td><b>Sharding / partitioning</b></td><td>Split data by a key (city, store, user id range) across servers</td><td>Cross-shard queries and transactions are harder</td></tr>
<tr><td><b>Caching</b></td><td>Keep popular answers in memory</td><td>Must expire or refresh, or users see old data</td></tr>
<tr><td><b>Indexing</b></td><td>Pre-built lookups</td><td>More storage, slower writes</td></tr>
<tr><td><b>Load balancer</b></td><td>Spreads requests across many servers</td><td>Needs health checks</td></tr>
<tr><td><b>CDN</b></td><td>Serves images and files from nearby servers</td><td>Cache invalidation</td></tr></table>
<h3>CAP theorem in one minute</h3><p>When a network splits and servers cannot talk to each other, a system must choose between <b>Consistency</b> (everyone sees the same truth, so some requests are refused) and <b>Availability</b> (always answer, maybe with stale data). <b>Partition tolerance</b> is not optional on a real network.</p>
<table><tr><th>Choose consistency (CP)</th><th>Choose availability (AP)</th></tr><tr><td>Payments, final stock decrement, seat booking</td><td>Product browsing, recommendations, view counts, "30 people watching"</td></tr></table>
<p><b>BASE</b> is the NoSQL counterpart of ACID: <i>Basically Available, Soft state, Eventually consistent</i>. "Eventually" means copies agree after a short delay, often milliseconds.</p>
<div class="box"><b>Quorum rule:</b> with N copies, if reads (R) and writes (W) each touch enough copies so that <b>R + W &gt; N</b>, a read always sees the latest write. Example: N=3, R=2, W=2.</div>""",
  ["Replication, sharding, caching and indexing are the four scaling tools.", "CAP: during a network split you cannot have both perfect consistency and perfect availability.", "Use strong consistency only where wrong data costs money or trust."], "Classify ten features of a shopping app as 'must be exact' or 'can be a bit stale'."),

 ("intermediate", "The inventory problem: never sell the last item twice", "Walk the whiteboard's qty = 1 problem and its fixes.", ill_flow(["Browse: show 'in stock'", "Add to cart: soft hold for a few minutes", "Pay: confirm the hold", "Deduct stock, create order", "Timeout: release the hold"], "Inventory reservation flow") + r"""
<p>Two customers see "1 left" and tap Buy at the same moment. If both read <code>qty = 1</code> and both subtract, you sell two and have one. This is a <b>race condition</b>. The fix is to make the check and the subtraction one indivisible step.</p>
<table><tr><th>Approach</th><th>How it works</th><th>Good for</th></tr>
<tr><td><b>Atomic update</b></td><td><code>UPDATE … SET qty = qty - 1 WHERE qty &gt; 0</code>; if 0 rows changed, it is sold out</td><td>Simple, most cases</td></tr>
<tr><td><b>Pessimistic lock</b></td><td>Lock the row while one buyer decides</td><td>Rare, very hot items; can slow everyone</td></tr>
<tr><td><b>Optimistic lock</b></td><td>Read a version number; update only if it has not changed; else retry</td><td>Many readers, fewer conflicting buyers</td></tr>
<tr><td><b>Reservation (hold)</b></td><td>Reserve the item for 5-10 minutes during checkout, then confirm or release</td><td>Tickets, tatkal seats, flash sales</td></tr>
<tr><td><b>Queue per item</b></td><td>Put buyers in line and process one by one</td><td>Extreme flash sales</td></tr></table>
<h3>Other rules that protect money</h3><ul><li><b>Idempotency key:</b> a unique request ID so a retried tap or a repeated payment callback does not create a second order or second charge.</li><li><b>Two-phase commit (2PC):</b> several systems agree to commit together; strong but slow and fragile.</li><li><b>Saga:</b> a chain of steps, each with an undo ("refund", "release stock"). Popular in microservices.</li><li><b>Outbox pattern:</b> write the order and the "order created" event together, then publish the event, so none gets lost.</li></ul>
<div class="box"><b>Product choices:</b> how long is a hold (stock locked vs lost sales)? Do we show "only 2 left" (real-time cost vs urgency)? What do we do when payment fails after stock is held (auto-release, notify)?</div>""",
  ["The last-item problem is a race; fix it with one atomic step.", "Holds with a timeout balance sales and fairness.", "Idempotency keys stop double orders and double charges."], "Define hold time, release rule and message for a 'last seat' booking feature."),

 ("advanced", "Consensus: Paxos and Raft without the maths", "Understand why servers must agree and how they do it.", ill_cycle(["1. Propose a value", "2. Majority promises", "3. Accept the value", "4. Everyone learns it"], "Paxos in four moves") + r"""
<p>If four servers each keep a copy of the truth ("order 55 is paid"), what if two disagree? <b>Consensus</b> is how a group of servers agrees on one value even when some crash or messages are delayed. It is the engine behind reliable leaders, locks and configuration.</p>
<ul><li><b>Paxos</b> (Leslie Lamport): the classic algorithm. A <i>proposer</i> suggests a value, <i>acceptors</i> promise and accept, <i>learners</i> record the result. Two phases: <b>prepare/promise</b>, then <b>accept</b>. A value is chosen once a <b>majority (quorum)</b> accepts it.</li><li><b>Raft:</b> designed to be easier to understand. One <b>leader</b> takes all writes and copies them to followers. If the leader dies, a new election starts.</li><li><b>Majority math:</b> with N nodes you survive <code>floor((N-1)/2)</code> failures. 3 nodes tolerate 1, 5 nodes tolerate 2. The 4-node ring on the whiteboard tolerates only 1 (same as 3), which is why odd numbers are preferred.</li></ul>
<table><tr><th>Where you meet it</th><th>What it protects</th></tr><tr><td>etcd (Raft), ZooKeeper (ZAB), Consul</td><td>Cluster settings, leader election, distributed locks</td></tr><tr><td>Google Spanner (Paxos)</td><td>Globally consistent database</td></tr><tr><td>Cassandra light-weight transactions</td><td>"Insert only if not exists"</td></tr><tr><td>Kafka (KRaft)</td><td>Keeping the message cluster's metadata consistent</td></tr></table>
<div class="box"><b>What a PM should take away:</b> consensus gives <i>safety</i> but costs <i>speed</i>. Every write needs a majority round-trip, so spreading across regions makes writes slower. You rarely build it; you choose products that already use it, and you accept the latency and cost that come with strong consistency.</div>""",
  ["Consensus = servers agreeing on one value despite failures.", "Majority (quorum) is the core idea; odd numbers of nodes are best.", "Strong agreement costs latency, a trade-off PMs must price in."], "Explain in three sentences to a friend why four partners must agree before a ledger entry is final."),

 ("advanced", "Vector databases, geolocation and the AI parts", "Add meaning search, location and chatbots to the design.", ill_flow(["Customer question", "Turn into an embedding", "Vector DB finds similar help articles", "AI answers using them (RAG)", "Escalate to a human if unsure"], "A support chatbot with a vector database") + r"""
<h3>Vector databases</h3><p>An <b>embedding</b> is a list of numbers that captures the <i>meaning</i> of text, an image or a product. Similar meanings sit close together. A <b>vector database</b> stores embeddings and finds the nearest ones quickly (<b>ANN</b>, approximate nearest neighbour, using methods like HNSW). So "something to have with chai" can find biscuits and rusks, even without those exact words.</p>
<table><tr><th>Use</th><th>Example</th></tr><tr><td>Semantic search</td><td>Search that understands intent and Hinglish</td></tr><tr><td>RAG chatbot</td><td>Find the right policy or help article, then let the AI answer from it</td></tr><tr><td>Recommendations</td><td>"People who like this also like…"</td></tr><tr><td>Duplicate and fraud detection</td><td>Near-identical listings or reviews</td></tr></table>
<ul><li><b>Hybrid search:</b> combine keywords (BM25) with vectors, and add filters such as city, in stock, price.</li><li><b>Options:</b> a vector DB (Pinecone, Qdrant, Weaviate, Milvus) or the <b>pgvector</b> add-on to Postgres, often enough for starting out.</li><li><b>Watch:</b> re-embedding cost when content changes, relevance testing (evals), and privacy of what you embed.</li><li><b>Not for:</b> exact lookups like "order 55". Use SQL for those.</li></ul>
<h3>Geolocation</h3><ul><li>Store places as latitude and longitude; use <b>geohash</b> or Uber's <b>H3</b> hex grid to group nearby points fast.</li><li>Tools: PostGIS (Postgres), Redis GEO, Elasticsearch geo queries, Google Maps APIs.</li><li>Typical questions: which dark store is within 2 km and has stock? What is the ETA? Is this pin inside the service area?</li><li>Privacy: ask consent, collect only what you need, follow the DPDP Act.</li></ul>
<div class="box">AI and location features are additions to the same architecture: they read from the inventory and orders data, they do not replace the SQL ledger.</div>""",
  ["Vector DBs search by meaning, not exact words.", "RAG uses a vector DB to ground chatbot answers.", "Geohash and H3 make 'nearest store' fast."], "Design the vector-search and location steps for 'find me a 10-minute dinner nearby'."),

 ("advanced", "The supporting cast: APIs, queues, events and observability", "Know the other terms that appear in every design review.", r"""
<table><tr><th>Term</th><th>Plain meaning</th><th>Why a PM cares</th></tr>
<tr><td><b>API / REST / GraphQL</b></td><td>The doors through which apps and partners talk to your service</td><td>Contract with partners; versioning breaks apps</td></tr>
<tr><td><b>Monolith vs microservices</b></td><td>One big app vs many small services</td><td>Speed of teams vs operational complexity</td></tr>
<tr><td><b>Message queue (Kafka, RabbitMQ, SQS)</b></td><td>A line where work waits to be processed later</td><td>Handles spikes, avoids blocking the user</td></tr>
<tr><td><b>Event-driven / pub-sub</b></td><td>Services announce "order created" and others react</td><td>Loose coupling, but harder to trace</td></tr>
<tr><td><b>Webhook</b></td><td>A partner calls your URL when something happens</td><td>Payment status updates; needs retries and idempotency</td></tr>
<tr><td><b>Rate limiting / backoff</b></td><td>Cap requests; wait longer between retries</td><td>Prevents abuse and retry storms</td></tr>
<tr><td><b>Circuit breaker</b></td><td>Stop calling a failing service for a while</td><td>One failure does not take everything down</td></tr>
<tr><td><b>OLTP vs OLAP</b></td><td>Live transactions vs analytics and reporting</td><td>Do not run heavy reports on the live database</td></tr>
<tr><td><b>CDC</b></td><td>Change data capture: stream database changes elsewhere</td><td>Feeds search, analytics and caches</td></tr>
<tr><td><b>Feature flags / canary / blue-green</b></td><td>Release to a few users or switch between two versions</td><td>Safe rollouts and quick rollback</td></tr>
<tr><td><b>Observability</b></td><td>Logs, metrics and traces to see what is happening</td><td>Faster incident response; ask for dashboards in specs</td></tr></table>
<h3>Back-of-the-envelope sizing (a PM skill)</h3><p>1 million orders a day is about <b>12 orders per second</b> on average (1,000,000 / 86,400). Plan for peaks of 10x, so about <b>120 per second</b>. If each order takes 2 KB, that is about <b>2 GB a day</b> or roughly <b>730 GB a year</b>. Browsing is far larger than buying: expect 50 to 100 reads for every order, so cache hot data.</p>
<div class="box">Ask engineers: "What is our peak requests per second, our p99 latency, and what breaks first if traffic doubles?"</div>""",
  ["Know the vocabulary: API, queue, event, webhook, cache, observability.", "Queues and events absorb spikes but add complexity.", "Estimate scale with simple arithmetic before debating tools."], "Estimate requests per second and daily storage for an app with 200,000 orders a day."),

 ("advanced", "Case study and PM interview answer: design inventory and checkout", "Practise a complete answer from requirements to trade-offs.", r"""
<p><b>Prompt:</b> "Design inventory and checkout for a 10-minute grocery delivery app."</p>
<ol><li><b>Clarify:</b> users, cities, stores, items per store, flash sales? Out of scope: delivery routing.</li><li><b>Goals and metrics:</b> no overselling, checkout under 2 seconds p95, 99.95% availability, order success rate, refund rate.</li><li><b>Scale:</b> 1M orders/day, peak 10x, 100 reads per order.</li><li><b>High-level design:</b> app, API gateway, services (catalogue, inventory, order, payment, notifications), SQL for orders, key-value/Redis for carts and stock cache, Kafka for events, vector DB for support search, geolocation for the nearest store.</li><li><b>Deep dive (inventory):</b> per-store stock in a fast store, atomic decrement, 8-minute holds, release on timeout, reconcile with the vendor app hourly.</li><li><b>Failure modes:</b> payment succeeds but order write fails (saga plus idempotency), a node dies (replicas, quorum), vendor app offline (last-known stock, safety buffer).</li><li><b>Trade-offs:</b> consistency for stock and money, availability for browsing, cost of real-time counts.</li><li><b>Rollout:</b> pilot in one city, feature flags, dashboards, alerts, rollback plan.</li></ol>
<table><tr><th>Interviewers reward</th><th>Interviewers penalise</th></tr><tr><td>Clarifying questions, metrics, trade-offs, user impact, simple numbers</td><td>Tool name-dropping, no numbers, ignoring failure cases, over-engineering</td></tr></table>
<div class="box"><b>One-line answer:</b> "Strong consistency for stock and payments, eventual consistency for browsing, holds to protect the last item, idempotency to survive retries, and metrics to prove it works."</div>""",
  ["Answer in a fixed order: clarify, metrics, scale, design, deep dive, failures, trade-offs, rollout.", "Name the hard part and solve it.", "Tie every choice to a user or business outcome."], "Record yourself giving this answer in 5 minutes using the eight steps."),

 ("advanced", "Final project: write a one-page system brief", "Produce a PM-friendly design brief you can share with engineers.", r"""<p>Choose a product (food delivery, ticket booking, wallet, ed-tech) and write a one-page brief that answers:</p>
<ul><li>What are the 5 core data types and which database fits each (SQL, key-value, document, wide-column, vector)?</li><li>Which operations must be strongly consistent, and which can be eventually consistent?</li><li>How do you prevent double selling or double charging?</li><li>What scale and latency targets do you assume, and how did you estimate them?</li><li>What are the top 3 failure scenarios and your response?</li><li>What does it cost per 1,000 orders, and what is the lever to reduce it?</li></ul>
<p>Share it with an engineer and ask for the three biggest risks they see. Update the brief with their answers.</p>""",
  ["A good brief is short, numeric and honest about trade-offs.", "Engineers improve a draft faster than a blank page.", "Keep the brief updated as the product scales."], "Complete the one-page system brief and review it with an engineer."),
]

SERVICES = ("intermediate", "Services and servers: what happens when volume grows", "Follow the app from 100 users to 10 million without the jargon.", ill_stack([("Users", "from 1x to 100x traffic"), ("Load balancer", "spreads requests, drops unhealthy servers"), ("Many identical servers (stateless)", "autoscaling adds or removes copies"), ("Queue / cache", "absorb spikes, shield the database"), ("Databases", "replicas, shards, separate stores per job")], "Scaling path: every layer can be widened") + r"""
<p>A <b>server</b> is a computer running your code. A <b>service</b> is one job done by that code (catalogue, orders, payments). As more people use the app, you do not need smarter code first; you need <b>more copies of the same code</b> and a database layer that can keep up.</p>
<table><tr><th>Traffic</th><th>What the team does</th><th>PM impact</th></tr>
<tr><td><b>1x: launch day</b></td><td>One server and one database are enough. Keep it simple.</td><td>Ship features fast</td></tr>
<tr><td><b>5x</b></td><td>Add a <b>load balancer</b> and several identical servers; add a <b>cache</b> for hot data; add a <b>read replica</b>.</td><td>Page speed stays steady</td></tr>
<tr><td><b>20x: a sale or festival</b></td><td><b>Autoscaling</b> adds servers on demand; <b>queues</b> take slow work (emails, invoices) off the checkout path; <b>rate limits</b> protect the system.</td><td>Plan promotions with engineering; pre-warm for known peaks</td></tr>
<tr><td><b>100x: a national app</b></td><td><b>Shard</b> the database by city or user; split into <b>microservices</b>; use several regions; add a <b>CDN</b> for images.</td><td>Cost and team ownership become the main questions</td></tr></table>
<h3>The key ideas</h3><ul><li><b>Vertical scaling</b> = a bigger machine (simple, has a ceiling). <b>Horizontal scaling</b> = more machines (no ceiling, needs the design below).</li><li><b>Stateless services:</b> a server keeps no customer data in its own memory, so any server can answer any request and one can fail without anyone noticing. State lives in the database, cache or session store.</li><li><b>Autoscaling:</b> rules like "add a server when CPU is above 60%". It takes a minute or two, so it cannot catch a sudden 50x spike; prepare ahead.</li><li><b>Containers and Kubernetes:</b> packaging code so identical copies start fast and are managed automatically.</li><li><b>Queues and backpressure:</b> when work arrives faster than it can be done, put it in line instead of crashing; slow down or reject extra requests politely (HTTP 429).</li><li><b>Graceful degradation:</b> when overloaded, switch off the non-essential (recommendations, live counters) to protect checkout.</li><li><b>Bottlenecks move:</b> after servers, the database is next; after the database, a third-party API such as the payment gateway. Find the weakest link with a <b>load test</b>.</li><li><b>Circuit breakers and load shedding:</b> stop calling a failing dependency so one problem does not become a full outage.</li></ul>
<div class="box"><b>Sale-day checklist for a PM:</b> expected peak orders per second, load test passed at 2x that, autoscaling limits raised, cache warmed, payment gateway limits confirmed in writing, feature flags ready to switch off extras, on-call named, rollback plan.</div>""",
  ["Scale by adding identical stateless servers behind a load balancer.", "Protect the database with caches, replicas and queues.", "Find the next bottleneck with load tests before the sale, not during it."], "Write a sale-day plan for a 20x traffic spike: what scales, what is switched off, and who is on call.")

JOURNEY = ("intermediate", "The full user journey: every step, system and risk", "Follow one order from opening the app to delivery and refunds.", ill_flow(["Open app, login, location", "Browse and search", "Add to cart (stock hold)", "Address and delivery slot", "Pay (UPI, card, COD)", "Order confirmed", "Pick, pack, deliver, track", "Rate, refund, support"], "The customer journey as a chain of systems") + r"""
<table><tr><th>#</th><th>What the user does</th><th>Systems involved</th><th>Data</th><th>What can go wrong, and the protection</th></tr>
<tr><td>1</td><td>Opens the app, logs in with OTP, shares location</td><td>Auth service, SMS provider, geolocation</td><td>User profile (SQL), session (Redis)</td><td>OTP abuse (rate limit); duplicate accounts (unique verified phone); location consent</td></tr>
<tr><td>2</td><td>Sees the nearest store and products</td><td>Geo service, catalogue, search, vector search, cache, CDN</td><td>Catalogue (document store), stock snapshot (cache)</td><td>Stale stock (label as approximate); slow load (cache, CDN)</td></tr>
<tr><td>3</td><td>Adds items to the cart</td><td>Cart service, inventory service</td><td>Cart (key-value store), soft hold on stock</td><td>Cart lost (persist per user); hold never released (TTL)</td></tr>
<tr><td>4</td><td>Chooses address and slot, sees the total</td><td>Address, pricing, offers, tax services</td><td>Addresses and coupons (SQL)</td><td>Price changes mid-checkout (price lock per cart version); coupon abused (one use per user)</td></tr>
<tr><td>5</td><td>Taps Pay</td><td>Order service, payment gateway (UPI, cards, wallets)</td><td>Order (SQL) in status PENDING, payment record</td><td>Double tap or retry (idempotency); money taken but no order (reconciliation)</td></tr>
<tr><td>6</td><td>Sees "Order confirmed"</td><td>Webhook handler, order and inventory services, notifications</td><td>Order PAID, stock deducted</td><td>Late or repeated webhooks (dedupe by payment id); stock gone (auto refund)</td></tr>
<tr><td>7</td><td>Tracks the order</td><td>Vendor app, picker app, rider app, maps, event stream</td><td>Status events and rider pings (wide-column / stream)</td><td>Missed updates (event replay); wrong ETA (re-estimate)</td></tr>
<tr><td>8</td><td>Delivered; rates, returns or asks for help</td><td>Support, chatbot with vector search, refund service</td><td>Tickets and refunds (SQL), help articles (vector DB)</td><td>Refund repeated (refund idempotency); bot gives a wrong answer (guardrails, human handover)</td></tr></table>
<h3>Journey metrics a PM watches</h3><ul><li><b>Funnel:</b> browse, cart, checkout started, payment attempted, payment succeeded, delivered. Each drop has a cause: speed, trust, price, payment failure.</li><li><b>Payment success rate</b> (by method and bank), <b>order success rate</b>, <b>p95 checkout time</b>, <b>cancellation and refund rate</b>, <b>duplicate order rate</b> (target zero).</li><li><b>Support contacts per 100 orders</b> as a quality signal for the whole chain.</li></ul>
<div class="box"><b>Order states</b> (a simple state machine): CREATED, PAYMENT_PENDING, PAID, PACKED, OUT_FOR_DELIVERY, DELIVERED, with side exits CANCELLED, FAILED and REFUNDED. Only allowed moves are accepted, which is what makes repeated or out-of-order messages harmless.</div>""",
  ["Every journey step touches different systems and data stores.", "Each step has a named risk and a named protection.", "An order state machine keeps messy real life under control."], "Map your own app's journey in the same table and add the metric you would track at each step.")

PAYMENT = ("advanced", "Payment checkout in detail", "Understand how a payment really moves, and why it is asynchronous.", ill_flow(["Create order PENDING with idempotency key", "Create payment with the gateway", "User pays in UPI app or card page", "Gateway sends a webhook", "Verify signature and amount", "Mark PAID, confirm stock", "Notify user; reconcile later"], "Checkout and payment: the safe sequence") + r"""
<p>Payments are <b>asynchronous</b>: your app starts a payment, the user finishes it in another app (UPI, bank page), and the gateway tells you the result later. The screen result can be wrong or lost, so the <b>server-to-server confirmation</b> is the truth.</p>
<ol><li><b>Create the order as PENDING</b> in SQL with a unique <b>idempotency key</b> made when the user starts checkout. Price, items and address are frozen on the order.</li><li><b>Create a payment</b> with the gateway (Razorpay, PayU, Cashfree, Stripe, UPI intent). You get a <b>payment id</b>. Store it against the order.</li><li><b>The user pays</b> in the UPI app or card page. Your app only shows "waiting for payment".</li><li><b>The gateway calls your webhook</b> with the result. Verify the <b>signature</b> and that the <b>amount and order id match</b>. Never trust the client app's "success".</li><li><b>Update in one transaction:</b> mark the order PAID, convert the stock hold into a deduction, write a ledger entry.</li><li><b>Publish an event</b> (outbox) so notifications, warehouse and analytics follow.</li><li><b>Reconcile:</b> a scheduled job compares your records with the gateway's settlement report and fixes mismatches (paid but no order, order but no payment).</li></ol>
<table><tr><th>Payment state</th><th>Meaning</th><th>What the app does</th></tr><tr><td>CREATED</td><td>Payment started</td><td>Wait; show a countdown</td></tr><tr><td>PENDING</td><td>Bank or UPI has not confirmed</td><td>Poll the gateway; do not charge again</td></tr><tr><td>AUTHORISED / CAPTURED</td><td>Money held / money taken</td><td>Confirm the order after capture</td></tr><tr><td>FAILED</td><td>Declined or timed out</td><td>Release stock, offer retry</td></tr><tr><td>REFUNDED / PARTIAL</td><td>Money returned</td><td>Update the order; notify</td></tr></table>
<h3>Edge cases to ask about</h3><ul><li><b>Money debited but the app shows failure:</b> keep the order PENDING until the gateway confirms; auto-refund after a defined window if the order cannot be fulfilled.</li><li><b>Webhook arrives twice, late or out of order:</b> handlers must be idempotent and obey the state machine.</li><li><b>User closes the app mid-payment:</b> the server still receives the webhook, so the order completes.</li><li><b>Gateway down:</b> fail over to a second gateway or show clear messaging; do not lose the cart.</li><li><b>Cash on delivery:</b> no gateway step, but the order still needs duplicate protection and fraud limits.</li><li><b>Security:</b> never store raw card numbers (use gateway tokens, PCI-DSS); encrypt personal data; follow RBI rules and the DPDP Act.</li></ul>""",
  ["The server-side webhook, not the app screen, decides success.", "Create the order first as PENDING, then confirm after verified payment.", "Reconciliation catches whatever the real-time flow misses."], "Draw the sequence of a UPI payment with five actors: user, app, your server, gateway, bank. Mark where a failure can occur.")

NEVER_TWICE = ("advanced", "Never twice: no repeated order, payment or customer", "Use layered protections so duplicates cannot happen, even with retries.", ill_stack([("1. Screen", "disable the button after the first tap, show a spinner"), ("2. API", "idempotency key on every create-order and pay request"), ("3. Database", "unique constraints make a duplicate impossible"), ("4. Events and webhooks", "dedupe by id, accept only valid state moves"), ("5. Reconciliation", "daily check against the gateway and a duplicate report")], "Five layers against duplicates") + r"""
<p>Networks fail, users double tap, apps retry, and webhooks repeat. Systems normally guarantee <b>at-least-once</b> delivery (a message may arrive twice). True "exactly once" is built by combining <b>at-least-once delivery</b> with <b>idempotent processing</b>. You need protections at several layers because any single one can fail.</p>
<h3>A. How to make sure an order is not repeated</h3>
<ul><li><b>Idempotency key:</b> the app generates one key per checkout attempt (for example cart id plus cart version). Every retry sends the same key. The server stores key to order id. A second request with the same key returns the <b>same order</b> instead of making a new one.</li><li><b>Unique constraint in SQL:</b> a unique index on <code>(user_id, idempotency_key)</code> means the database itself refuses a second row, even if the code has a bug or two servers race.</li><li><b>One active checkout per cart:</b> a short lock (Redis <code>SET key value NX EX 30</code>, or a row lock) so two simultaneous taps on two servers cannot both proceed.</li><li><b>Order state machine:</b> only legal moves are accepted, so a repeated "mark as paid" does nothing.</li><li><b>Time window rule:</b> if the same user, store and basket is submitted twice within a few seconds, show "you already placed this order" with a link to it.</li></ul>
<pre>CREATE UNIQUE INDEX uq_order_idem ON orders (user_id, idempotency_key);

INSERT INTO orders (user_id, idempotency_key, status, total)
VALUES (101, 'chk-7f3a', 'PAYMENT_PENDING', 349)
ON CONFLICT (user_id, idempotency_key) DO NOTHING;   -- a repeat inserts nothing
SELECT order_id FROM orders WHERE user_id = 101 AND idempotency_key = 'chk-7f3a';</pre>
<h3>B. How to make sure a payment is not repeated</h3>
<ul><li>Send the gateway an idempotency key or a unique receipt reference per payment so a retried API call cannot create two charges.</li><li>Store the gateway <b>payment id</b> with a <b>unique constraint</b>; a webhook for an id already processed is acknowledged (HTTP 200) and ignored.</li><li>One order has at most one <b>successful</b> payment. If a second success arrives, auto-refund it and alert.</li><li><b>Refunds:</b> an idempotency key per refund, and the refunded total never exceeds the paid total.</li><li>Reply quickly to a webhook and do heavy work asynchronously, so the gateway does not retry unnecessarily.</li></ul>
<h3>C. How to make sure no customer is repeated</h3>
<ul><li>Make the <b>verified mobile number</b> (and email, where used) <b>unique</b>, after normalising the format (+91, spaces, case).</li><li>Verify with an <b>OTP</b> before creating the account; use IDs from trusted logins (Google, Apple) as extra unique keys.</li><li>On signup, <b>check then insert inside one transaction</b>, backed by the unique index, so two simultaneous signups cannot both win.</li><li><b>Duplicate detection and merging:</b> match on phone, email, device and name or address similarity; merge accounts with a documented process that moves orders, wallet and loyalty points and keeps an audit trail.</li><li><b>Abuse and promos:</b> limit first-order offers per device, phone, payment instrument and address to stop repeat sign-ups.</li><li><b>Privacy:</b> keep only needed identifiers, protect them, and honour deletion requests under the DPDP Act.</li></ul>
<table><tr><th>Where duplicates come from</th><th>Fix</th></tr><tr><td>Double tap or slow screen</td><td>Disable the button; idempotency key</td></tr><tr><td>Client retry after timeout</td><td>Same key returns the same order</td></tr><tr><td>Two servers handle one request</td><td>Unique database constraint; short lock</td></tr><tr><td>Webhook sent twice</td><td>Dedupe by payment id; state machine</td></tr><tr><td>Queue redelivers a message</td><td>Idempotent consumer; processed-message table</td></tr><tr><td>Same person signs up twice</td><td>Unique verified phone; merge process</td></tr></table>
<div class="box"><b>Test it:</b> include duplicate scenarios in QA: double tap, kill the server mid-payment, replay the webhook five times, send the same signup from two phones. The target metric is <b>zero duplicate orders and zero duplicate charges</b>, tracked daily.</div>""",
  ["Idempotency key plus a unique database constraint is the core defence.", "Make every webhook and queue consumer idempotent.", "Protect customers too: unique verified phone, OTP, merge process."], "Write the duplicate-protection checklist for your product's checkout, signup and refund flows.")

